def solve(payload):
    ps = payload["particles"]
    if any(p["mass_kg"] < 0 for p in ps):
        return {"error": "negative_mass"}
    total = sum(p["mass_kg"] for p in ps)
    if total == 0:
        return {"error": "zero_mass"}
    center = [sum(p["mass_kg"]*p["position_m"][i] for p in ps)/total for i in range(3)]
    tensor = [[0.0]*3 for _ in range(3)]
    for p in ps:
        d = [p["position_m"][i]-center[i] for i in range(3)]
        d2 = sum(x*x for x in d)
        for i in range(3):
            for j in range(3):
                tensor[i][j] += p["mass_kg"]*((d2 if i == j else 0)-d[i]*d[j])
    return {"mass_kg": total, "center_m": center, "inertia_kg_m2": tensor}

